class Stack:

    def __init__(self):
        self.stack = []

    # Add to the top of stack
    def push(self, data):
        self.stack.append(data)

    # Remove from the top of stack
    def pop(self):
        if self.stack:
            return self.stack.pop()

    # Peek top element
    def peek(self):
        return self.stack[-1]

    # Check if stack is empty
    def is_empty(self):
        return not bool(self.stack)

