    def circumference(self):
        return 2 * 3.14 * self.radius

def solve_sudoku(board): 

    find = find_empty_location(board) 
    if not find: 
        return True
    else: 
        row, col = find 

    for i in range(1,10): 
        if is_valid(board, i, (row, col)): 
            board[row][col] = i 

            if solve_sudoku(board): 
                return True

            # Undo the current cell for backtracking 
            board[row][col] = 0

